import{_ as a,o as e,c as r,ag as l}from"./chunks/framework.D7Pdja0E.js";const c=JSON.parse('{"title":"구성원 관리","description":"","frontmatter":{},"headers":[],"relativePath":"03-dept-admin-guide/members.md","filePath":"03-dept-admin-guide/members.md","lastUpdated":1776160579000}'),i={name:"03-dept-admin-guide/members.md"};function o(d,t,n,s,h,m){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="구성원-관리" tabindex="-1">구성원 관리 <a class="header-anchor" href="#구성원-관리" aria-label="Permalink to &quot;구성원 관리&quot;">​</a></h1><p>부서 관리자는 소속 부서의 구성원을 관리합니다.</p><h2 id="구성원-목록-조회" tabindex="-1">구성원 목록 조회 <a class="header-anchor" href="#구성원-목록-조회" aria-label="Permalink to &quot;구성원 목록 조회&quot;">​</a></h2><p>사이드바 &gt; <strong>관리</strong> &gt; <strong>부서 관리</strong>에서 소속 부서의 구성원 목록을 확인합니다.</p><p>각 구성원의 다음 정보가 표시됩니다:</p><ul><li>이름</li><li>이메일</li><li>직급</li><li>역할 (admin / member / guest)</li><li>상태 (활성 / 비활성)</li></ul><h2 id="구성원-역할-변경" tabindex="-1">구성원 역할 변경 <a class="header-anchor" href="#구성원-역할-변경" aria-label="Permalink to &quot;구성원 역할 변경&quot;">​</a></h2><ol><li>구성원 목록에서 대상 사용자를 선택합니다.</li><li><strong>역할</strong> 드롭다운에서 새 역할을 선택합니다.</li><li>변경 사항이 즉시 적용됩니다.</li></ol><h3 id="역할별-권한" tabindex="-1">역할별 권한 <a class="header-anchor" href="#역할별-권한" aria-label="Permalink to &quot;역할별 권한&quot;">​</a></h3><table tabindex="0"><thead><tr><th>역할</th><th>권한</th></tr></thead><tbody><tr><td>admin</td><td>부서 설정, 구성원 관리, 채널/프로젝트 관리</td></tr><tr><td>member</td><td>채널 참여, 프로젝트 참여, 메시지, 태스크</td></tr><tr><td>guest</td><td>읽기 전용</td></tr></tbody></table><h2 id="구성원-추가" tabindex="-1">구성원 추가 <a class="header-anchor" href="#구성원-추가" aria-label="Permalink to &quot;구성원 추가&quot;">​</a></h2><ol><li>구성원 목록 화면에서 <strong>&quot;+ 구성원 추가&quot;</strong> 버튼을 클릭합니다.</li><li>조직 내 사용자를 검색하여 선택합니다.</li><li>역할을 지정하고 추가합니다.</li></ol><blockquote><p><strong>참고</strong>: 사용자 계정 생성은 기관 관리자 권한입니다. 부서 관리자는 이미 등록된 사용자를 부서에 배정하는 역할을 합니다.</p></blockquote><h2 id="구성원-제거" tabindex="-1">구성원 제거 <a class="header-anchor" href="#구성원-제거" aria-label="Permalink to &quot;구성원 제거&quot;">​</a></h2><ol><li>구성원 목록에서 대상 사용자의 <strong>제거</strong> 버튼을 클릭합니다.</li><li>확인 후 해당 사용자가 부서에서 제거됩니다.</li><li>사용자 계정 자체는 삭제되지 않으며, 다른 부서에는 영향이 없습니다.</li></ol>',15)])])}const b=a(i,[["render",o]]);export{c as __pageData,b as default};
